-- MySQL 8 / MariaDB; import into an empty database.
CREATE TABLE IF NOT EXISTS offices(id INTEGER PRIMARY KEY AUTO_INCREMENT,code VARCHAR(20) NOT NULL UNIQUE,name VARCHAR(160) NOT NULL,head VARCHAR(160),supervisor VARCHAR(160),contact VARCHAR(160),status VARCHAR(30) NOT NULL DEFAULT 'Active') ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(160) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role VARCHAR(40) NOT NULL,office_id INTEGER NOT NULL,position VARCHAR(160),status VARCHAR(30) DEFAULT 'Active',FOREIGN KEY (office_id) REFERENCES offices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicles(id INTEGER PRIMARY KEY AUTO_INCREMENT,model VARCHAR(160) NOT NULL,type VARCHAR(40) NOT NULL,plate VARCHAR(40) NOT NULL UNIQUE,property_number VARCHAR(80),capacity INTEGER NOT NULL,odometer INTEGER NOT NULL DEFAULT 0,registration_expiry DATE,condition_text VARCHAR(160),status VARCHAR(40) NOT NULL,photo_url VARCHAR(255)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS drivers(id INTEGER PRIMARY KEY AUTO_INCREMENT,full_name VARCHAR(160) NOT NULL,employee_number VARCHAR(80) NOT NULL UNIQUE,office_id INTEGER,contact VARCHAR(80),license_number VARCHAR(80),license_expiry DATE NOT NULL,status VARCHAR(40) NOT NULL,FOREIGN KEY (office_id) REFERENCES offices(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS requisitions(id INTEGER PRIMARY KEY AUTO_INCREMENT,reference VARCHAR(40) UNIQUE,requester_id INTEGER NOT NULL,office_id INTEGER NOT NULL,vehicle_type VARCHAR(40) NOT NULL,vehicle_id INTEGER,driver_id INTEGER,preferred_driver VARCHAR(160),passengers TEXT NOT NULL,start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,destination VARCHAR(255) NOT NULL,purpose TEXT NOT NULL,fuel_allocation INTEGER DEFAULT 0,fuel_quantity DECIMAL(10,2) DEFAULT 0,fuel_remarks TEXT,status VARCHAR(50) NOT NULL,created_at DATETIME NOT NULL,FOREIGN KEY (requester_id) REFERENCES users(id),FOREIGN KEY (office_id) REFERENCES offices(id),FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),FOREIGN KEY (driver_id) REFERENCES drivers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE INDEX idx_schedule ON requisitions(vehicle_id,status,start_datetime,end_datetime);
CREATE INDEX idx_driver_schedule ON requisitions(driver_id,status,start_datetime,end_datetime);
CREATE TABLE IF NOT EXISTS approvals(id INTEGER PRIMARY KEY AUTO_INCREMENT,requisition_id INTEGER NOT NULL,user_id INTEGER NOT NULL,stage VARCHAR(40) NOT NULL,decision VARCHAR(40) NOT NULL,remarks TEXT,created_at DATETIME NOT NULL,FOREIGN KEY (requisition_id) REFERENCES requisitions(id),FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicle_movements(id INTEGER PRIMARY KEY AUTO_INCREMENT,requisition_id INTEGER NOT NULL UNIQUE,departure DATETIME NOT NULL,return_time DATETIME,odometer_out INTEGER NOT NULL,odometer_in INTEGER,condition_text VARCHAR(160),remarks TEXT,checked_by INTEGER,FOREIGN KEY (requisition_id) REFERENCES requisitions(id),FOREIGN KEY (checked_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS vehicle_blocks(id INTEGER PRIMARY KEY AUTO_INCREMENT,vehicle_id INTEGER NOT NULL,start_datetime DATETIME NOT NULL,end_datetime DATETIME NOT NULL,reason TEXT NOT NULL,created_by INTEGER,FOREIGN KEY (vehicle_id) REFERENCES vehicles(id),FOREIGN KEY (created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS notifications(id INTEGER PRIMARY KEY AUTO_INCREMENT,user_id INTEGER NOT NULL,message TEXT NOT NULL,requisition_id INTEGER,is_read INTEGER DEFAULT 0,created_at DATETIME NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id),FOREIGN KEY (requisition_id) REFERENCES requisitions(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS audit_logs(id INTEGER PRIMARY KEY AUTO_INCREMENT,user_id INTEGER,action VARCHAR(100) NOT NULL,details TEXT,created_at DATETIME NOT NULL,FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS print_logs(id INTEGER PRIMARY KEY AUTO_INCREMENT,requisition_id INTEGER,user_id INTEGER,created_at DATETIME NOT NULL,FOREIGN KEY (requisition_id) REFERENCES requisitions(id),FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS system_settings(setting_key VARCHAR(80) PRIMARY KEY,setting_value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_attempts(id INTEGER PRIMARY KEY AUTO_INCREMENT,identity_hash VARCHAR(64) NOT NULL,attempted_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
